import * as echarts from 'echarts';


import {
  queryInstanceTodoTaskCount,
  queryInstanceTodoTaskCountByProcessKey
} from '@/api/workflow/analyse/todoTaskAnalysis';
import showListOrEchart from '../../../components/dataPickerTabs/showListOrEchart.vue';

let resizeObserve = null;

export default {
  name: 'TodoTaskAnalysis',
  components: {
    showListOrEchart
  },
  props: {},
  data() {
    return {
      isList: false,
      checked: false,
      options: [
        {
          value: '5',
          label: '前5名'
        },
        {
          value: '10',
          label: '前10名'
        },
        {
          value: '15',
          label: '前15名'
        },
        {
          value: '20',
          label: '前20名'
        }
      ],
      size: '5',
      myChart: null, // 环图
      doughnutData: [], // 待办任务环图数据
      todoTaskListData: [], // 待办任务列表数据
      todoTaskListByKeyData: [], // 代办任务下钻列表数据
      copyData: [], // 下钻列表数据备份
      listParam: {}, // 下钻列表参数
      dialogTableVisible: false, // 下钻列表是否弹出
      searchContent: '', // 搜索内容
      loading: false,
      current: 1,
      pageSize: 10,
      total: 10,
      isGetResult: false, // 是否获取到查询结果
      isLoading: false,
      processName: '', // 流程名称
      processTaskCount: '' // 待办任务数量
    };
  },
  computed: {
    doughnutOption() {
      const self = this;
      const data = [];
      self.doughnutData.forEach(item => {
        const obj = {};
        obj.value = item.processTaskCount;
        obj.name = item.processName;
        obj.processKey = item.processKey;
        data.push(obj);
      });
      return {
        color: [
          '#2794F8',
          '#FFBB00',
          '#EE7B4E',
          '#52C566',
          '#6F5EF9',
          '#6DC8EC',
          '#945FB9',
          '#FF9845',
          '#1E9493',
          '#FF99C3',
          '#BDD2FD',
          '#BDD2FD',
          '#5AD8A6',
          '#BDEFDB',
          '#5D7092',
          '#C2C8D5',
          '#F6BD16',
          '#FBE5A2',
          '#E8684A',
          '#F6C3B7'
        ],
        tooltip: {
          trigger: 'item',
          borderWidth: 0,
          backgroundColor: 'rgba(111, 111, 111, 1)',
          textStyle: {
            color: '#fff',
            fontWeight: '400'
          },
          confine: true,
          extraCssText: 'white-space: normal; word-break: break-all;'
        },
        legend: {
          type: 'scroll',
          top: '0',
          right: 0,
          icon: 'circle',
          itemWidth: 9,
          itemHeight: 9,
          textStyle: {
            color: '#8C8C8C'
          },
          padding: 0,
          formatter: function (name) {
            return echarts.format.truncateText(name, 100, '12px', '...');
          },
          tooltip: {
            show: false
          }
        },
        series: [
          {
            type: 'pie',
            radius: ['35%', '55%'],
            minAngle: 3,
            avoidLabelOverlap: true,
            itemStyle: {
              borderColor: '#fff',
              borderWidth: 2
            },
            top: 20,
            label: {
              show: true,
              color: '#545672',
              formatter: '{b}\n{c}个',
              padding: [5, 5, 5, 5],
              lineHeight: 17
            },
            labelLine: {
              show: true,
              length: 40,
              length2: 60,
              lineStyle: {
                width: 1,
                color: '#545672'
              }
            },
            data
          }
        ]
      };
    }
  },
  watch: {
    doughnutOption() {
      this.drawDoughnut();
    }
  },
  mounted() {
    this.doughnutDataLoad(this.size);
    this.todoTaskListLoad(this.size);
    resizeObserve = new ResizeObserver(() => {
      if (this.myChart) this.myChart.resize();
    });
    resizeObserve.observe(document.getElementById('processOverviewContent'));
  },
  beforeUnmount() {
    resizeObserve.disconnect();
  },
  methods: {
    // 搜索
    searchProcess(value) {
      const self = this;
      self.loading = true;
      self.pageSize = 10;
      self.current = 1;
      self.todoTaskListByKeyLoad(
        self.listParam,
        self.pageSize,
        self.current,
        value
      );
    },

    // 重置
    clearData() {
      const self = this;
      self.loading = true;
      self.searchContent = '';
      self.current = 1;
      self.pageSize = 10;
      self.loading = true;
      self.todoTaskListByKeyLoad(
        self.listParam,
        self.pageSize,
        self.current,
        self.searchContent
      );
    },

    // 数据下钻打开弹窗
    isDialogTable(row, column) {
      const self = this;
      self.searchContent = '';
      self.listParam = {};
      self.total = 0;
      self.todoTaskListByKeyData = [];
      if (column.label !== '流程名称' && column.label !== '序号') {
        self.dialogTableVisible = !self.dialogTableVisible;
      }
      self.listParam = {
        processKey: row.processKey
      };
      self.processName = row.processName;
      self.processTaskCount = row.processTaskCount;
      self.loading = true;
      self.pageSize = 10;
      self.current = 1;
      self.todoTaskListByKeyLoad(
        self.listParam,
        self.pageSize,
        self.current,
        self.searchContent
      );
    },

    // 每页显示几条数据
    handleSizeChange(value) {
      const self = this;
      self.pageSize = value;
      self.loading = true;
      self.todoTaskListByKeyLoad(
        self.listParam,
        self.pageSize,
        self.current,
        self.searchContent
      );
    },

    // 列表页码切换
    handleCurrentChange(value) {
      const self = this;
      self.current = value;
      self.loading = true;
      self.todoTaskListByKeyLoad(
        self.listParam,
        self.pageSize,
        self.current,
        self.searchContent
      );
    },

    // 查询
    queryType(value) {
      const self = this;
      self.isGetResult = false;
      self.todoTaskListLoad(value);
      self.doughnutDataLoad(value);
    },
    // 清除
    clearValue() {
      this.size = '5';
      this.queryType(this.size);
    },

    // 查看列表
    isShowList(value) {
      const self = this;
      self.isList = value;
      self.$nextTick(() => {
        self.drawDoughnut();
      });
    },

    // 绘制环图
    drawDoughnut() {
      const self = this;
      if (self.myChart) {
        self.myChart.dispose();
        self.myChart = null;
      }
      if (
        !this.$refs.todoTaskCharts ||
        this.$refs.todoTaskCharts.clientWidth === 0
      )
        return;
      // 基于准备好的dom，初始化echarts实例
      self.myChart = echarts.init(this.$refs.todoTaskCharts);
      self.myChart.setOption(self.doughnutOption);
      self.myChart.off('click');
      self.myChart.on('click', function (param) {
        self.searchContent = '';
        self.listParam = {};
        self.total = 0;
        self.todoTaskListByKeyData = [];
        self.dialogTableVisible = !self.dialogTableVisible;
        self.listParam = {
          processKey: param.data.processKey
        };
        self.processName = param.data.name;
        self.processTaskCount = param.data.value;
        self.loading = true;
        self.pageSize = 10;
        self.current = 1;
        self.todoTaskListByKeyLoad(
          self.listParam,
          self.pageSize,
          self.current,
          self.searchContent
        );
      });
    },

    // 待办任务排行查询
    doughnutDataLoad(value) {
      const self = this;
      const data = {
        size: value
      };
      queryInstanceTodoTaskCount(data)
        .then(res => {
          if (res.code === 10000 && res.data && res.data.records.length > 0) {
            self.doughnutData = res.data.records;
            self.isGetResult = false;
            self.$nextTick(() => {
              self.drawDoughnut();
            });
          } else {
            self.doughnutData = [];
            self.isGetResult = true;
          }
        })
        .catch(() => {
           this.$message({
            message: '',
            type: 'error'
          });
        });
    },

    // 待办任务排行查询
    todoTaskListLoad(value) {
      const self = this;
      self.isLoading = true;
      const data = {
        size: value
      };
      queryInstanceTodoTaskCount(data)
        .then(res => {
          if (res.code === 10000) {
            self.todoTaskListData = res.data.records;
            self.isLoading = false;
          }
        })
        .catch(() => {
           this.$message({
            message: '数据请求失败',
            type: 'error'
          });
        });
    },

    // 流程下钻到流程名称
    todoTaskListByKeyLoad(value, size, current, keyword) {
      const self = this;
      const data = {
        current, // 当前页
        size, // 每页显示条数
        keyword,
        processKey: value.processKey
      };
      queryInstanceTodoTaskCountByProcessKey(data)
        .then(res => {
          if (res.code === 10000) {
            self.todoTaskListByKeyData = res.data.records;
            self.copyData = res.data.records;
            self.total = res.data.total;
            self.loading = false;
          }
        })
        .catch(() => {
           this.$message({
            message: '数据请求失败',
            type: 'error'
          });
        });
    }
  }
};
